export function generateScaffold(file, viablyAnalysis) {
  const { path, type, purpose } = file;
  const ext = path.split('.').pop();

  const header = `/**
 * ${purpose}
 * Feature: ${viablyAnalysis.feature_name}
 * Generated by Viably AI
 */\n\n`;

  if (ext === 'tsx') return generateTSXComponent(path, header, purpose);
  if (ext === 'ts' || ext === 'js') return generateTypeScriptFile(path, header, purpose);
  if (ext === 'py') return generatePythonFile(path, header, purpose);
  if (path.includes('test')) return generateTestFile(path, header, ext);

  return `${header}// TODO: Implement ${path}\n`;
}

function generateTSXComponent(path, header, purpose) {
  const componentName = getComponentName(path);
  return `${header}import React, { useState, useEffect } from 'react';

interface ${componentName}Props {
  userId?: string;
  onComplete?: () => void;
}

/**
 * ${componentName} Component
 * Purpose: ${purpose}
 */
export const ${componentName}: React.FC<${componentName}Props> = ({ userId, onComplete }) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // TODO: Initialize component
    console.log('${componentName} mounted');
  }, []);

  const handleSubmit = async () => {
    setLoading(true);
    try {
      // TODO: Implement ${purpose}
      console.log('Processing...');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="${componentName.toLowerCase()}-container">
      <h2>${componentName}</h2>
      {error && <div className="error">{error}</div>}
      <button onClick={handleSubmit} disabled={loading}>
        {loading ? 'Processing...' : 'Submit'}
      </button>
      {/* TODO: Add additional UI elements for ${purpose} */}
    </div>
  );
};

export default ${componentName};
`;
}

function generateTypeScriptFile(path, header, purpose) {
  const moduleName = getComponentName(path);
  const isService = path.includes('service');
  const isAPI = path.includes('api');

  if (isAPI) {
    return `${header}import axios, { AxiosInstance } from 'axios';

const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';

export class ${moduleName} {
  private client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: API_BASE_URL,
      headers: {
        'Content-Type': 'application/json',
      },
    });
  }

  /**
   * ${purpose}
   */
  async execute(params: any): Promise<any> {
    try {
      const response = await this.client.post('/api/endpoint', params);
      return response.data;
    } catch (error) {
      console.error('API error:', error);
      throw error;
    }
  }

  // TODO: Add additional API methods
}

export default new ${moduleName}();
`;
  }

  if (isService) {
    return `${header}/**
 * ${moduleName} Service
 * Purpose: ${purpose}
 */
export class ${moduleName} {
  private initialized: boolean = false;

  constructor() {
    this.initialize();
  }

  private initialize(): void {
    // TODO: Initialize service
    this.initialized = true;
  }

  async process(data: any): Promise<any> {
    if (!this.initialized) {
      throw new Error('Service not initialized');
    }

    try {
      // TODO: Implement ${purpose}
      return { success: true, data };
    } catch (error) {
      console.error('Service error:', error);
      throw error;
    }
  }

  // TODO: Add business logic methods
}

export default new ${moduleName}();
`;
  }

  return `${header}export class ${moduleName} {
  constructor() {
    // TODO: Initialize
  }

  // TODO: Implement ${purpose}
}

export default ${moduleName};
`;
}

function generatePythonFile(path, header, purpose) {
  const className = getClassName(path);
  return `${header}"""${purpose}"""

class ${className}:
    """${className} implementation"""

    def __init__(self):
        pass

    # TODO: Implement methods

if __name__ == "__main__":
    pass
`;
}

function generateTestFile(path, header, ext) {
  if (ext === 'tsx' || ext === 'ts') {
    return `${header}import { describe, it, expect } from 'vitest';

describe('Feature Test', () => {
  it('should work correctly', () => {
    expect(true).toBe(true);
  });
});
`;
  }

  if (ext === 'py') {
    return `${header}"""Test suite"""
import unittest

class TestFeature(unittest.TestCase):
    def test_basic(self):
        self.assertTrue(True)

if __name__ == '__main__':
    unittest.main()
`;
  }

  return `${header}// TODO: Implement tests\n`;
}

function getComponentName(path) {
  const filename = path.split('/').pop().split('.')[0];
  return filename.split(/[-_]/).map(word => word.charAt(0).toUpperCase() + word.slice(1)).join('');
}

function getClassName(path) {
  return getComponentName(path);
}
